cd /tmp/vally-eval-trial-DQ4Nye && mkdir -p docs/features/pricing tests/CheckoutPricing.UnitTest/Features/Discount .copilot-tracking/skraft-plans/pricing/details/2026-08-12
cat > docs/features/pricing/discount.feature <<'EOF'
@discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: the four scenarios below (AC-1 to AC-4), values copied verbatim.
  # NOT DECIDED, so deliberately no scenario and no test:
  #   - Platinum tier: no reduction agreed by the business (AC "Not decided").
  #   - Rounding rule beyond the single AC-4 example (see open questions in the test plan).

  @happy-path
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer is charged a whole-cent total for a very small basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/DiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    [Fact]
    // Bronze customer is charged the Bronze price for a basket
    public void Bronze_customer_is_charged_the_Bronze_price_for_a_basket()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~DiscountAcceptanceTests" 2>&1 | tail -20

